#include <hipblas/hipblas.h>
#include <hip/hip_runtime.h>
#include <stdio.h>

#define HIPBLAS_CHECK(call) { hipblasStatus_t err = call; if (err != HIPBLAS_STATUS_SUCCESS) { fprintf(stderr, "hipBLAS error %d at %s:%d\n", err, __FILE__, __LINE__); exit(1); } }
#define HIP_CHECK(call) { hipError_t err = call; if (err != hipSuccess) { fprintf(stderr, "HIP error: %s at %s:%d\n", hipGetErrorString(err), __FILE__, __LINE__); exit(1); } }

static hipblasHandle_t g_hipblas = nullptr;
void ensure_hipblas() {
    if (!g_hipblas) {
        HIPBLAS_CHECK(hipblasCreate(&g_hipblas));
    }
}

void gpu_sgemm(const float* A, const float* B, float* C,
               int m, int n, int k, float alpha, float beta) {
    ensure_hipblas();
    HIPBLAS_CHECK(hipblasSgemm(g_hipblas, HIPBLAS_OP_N, HIPBLAS_OP_N,
                               n, m, k,
                               &alpha, B, n, A, k, &beta, C, n));
}

#include <hipfft/hipfft.h>
#include <hip/hip_runtime.h>
#include <stdio.h>

#define HIPFFT_CHECK(call) { hipfftResult e = call; if (e != HIPFFT_SUCCESS) { fprintf(stderr, "hipFFT error %d at %s:%d\n", e, __FILE__, __LINE__); exit(1); } }

void gpu_rfft(const float* input, hipfftComplex* output, int n) {
    hipfftHandle plan;
    HIPFFT_CHECK(hipfftPlan1d(&plan, n, HIPFFT_R2C, 1));
    float* d_input;
    hipfftComplex* d_output;
    hipMalloc(&d_input, n * sizeof(float));
    hipMalloc(&d_output, (n/2+1) * sizeof(hipfftComplex));
    hipMemcpy(d_input, input, n * sizeof(float), hipMemcpyHostToDevice);
    HIPFFT_CHECK(hipfftExecR2C(plan, d_input, d_output));
    hipMemcpy(output, d_output, (n/2+1) * sizeof(hipfftComplex), hipMemcpyDeviceToHost);
    hipfftDestroy(plan);
    hipFree(d_input);
    hipFree(d_output);
}
